(()=>{const f=document.createElement("iframe");f.title="T-018: Мультисплит и Mini-VRF";f.style.cssText="position:fixed;inset:0;width:100%;height:100dvh;border:0;z-index:999999;background:white";f.srcdoc="<!doctype html><html lang=\"ru\"><head><meta charset=\"UTF-8\"><meta name=\"robots\" content=\"noindex, nofollow, noarchive\"><meta name=\"googlebot\" content=\"noindex, nofollow, noarchive\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>T-018: Мультисплит и Mini-VRF</title><link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\"><style>:root{--blue:#0066ff;--navy:#0033a0;--red:#e81c1c;--ink:#1a1a1a;--muted:#606f85;--line:#e1e8f0;--bg:#f3f6fa}*{box-sizing:border-box}body{margin:0;font:14px Inter,Arial;color:var(--ink);background:var(--bg)}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid var(--line);border-radius:8px;background:white;padding:10px 14px;color:var(--navy)}button:hover{border-color:var(--blue);background:#e9f4ff}button:disabled{cursor:not-allowed;opacity:.5}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #80b3ff;outline-offset:2px}aside{position:fixed;width:238px;background:white;height:100vh;border-right:1px solid var(--line);padding:30px 20px}aside img{width:192px;height:auto}.space-label{font-size:9px;letter-spacing:1.5px;color:var(--muted);margin-top:40px}aside h3{font-size:16px;margin:12px 8px 28px}small{color:var(--muted);font-size:11px;font-weight:400}nav button{display:flex;gap:12px;align-items:center;border:0;width:100%;text-align:left;margin:7px 0;padding:13px;color:var(--muted);background:transparent}nav button.active{background:#e9f4ff;color:var(--navy);font-weight:600}nav .ico{font-size:19px;width:22px}nav .count{margin-left:auto;background:white;border-radius:5px;padding:2px 5px;font-size:11px}.side-bottom{position:absolute;bottom:30px;line-height:24px;font-size:12px}.dot{display:inline-block;background:var(--blue);width:7px;height:7px;border-radius:50%}main{margin-left:238px;padding:0 36px}header{height:76px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:11px}header b{padding:0 8px;color:#a9b5c6}header button{background:transparent;border:0;font-size:11px}.heading{display:flex;align-items:center;justify-content:space-between;padding:36px 0 24px}.eyebrow{letter-spacing:1.6px;color:var(--blue);font-size:10px;font-weight:700}h1{font-size:30px;letter-spacing:-1.1px;margin:12px 0}p{color:var(--muted);line-height:1.6;margin:6px 0}h2{font-size:20px;margin:0}.primary{background:var(--red);color:white;border-color:var(--red);padding:13px 20px}.primary:hover{background:#c41212;color:white;border-color:#c41212}.notice{border:1px solid #cadcf5;background:#eaf3ff;border-radius:10px;padding:14px 16px;font-size:11px;display:flex;align-items:center;gap:7px;line-height:1.5}.notice strong{color:var(--navy);white-space:nowrap}.notice button{margin-left:auto;padding:3px;background:transparent;border:0;white-space:nowrap}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:24px 0}.stat{background:white;border:1px solid var(--line);border-radius:12px;padding:20px}.stat label{color:var(--muted);font-size:12px}.stat b{display:block;font-size:30px;font-weight:600;margin:10px 0}.stat small{font-size:10px}.stat .stat-icon{float:right;color:var(--blue);font-size:20px}.route{display:flex;gap:20px;align-items:center;justify-content:space-between;background:white;border:1px solid var(--line);border-radius:12px;padding:20px}.route strong{font-size:12px}.route small{display:block;margin-top:6px;font-size:10px}.steps{display:flex;align-items:center;gap:10px;font-size:9px;font-weight:600;color:var(--navy)}.steps span{padding:9px;background:#f0f6ff;border-radius:5px}.steps i{color:#9cabc0}.section-title{display:flex;justify-content:space-between;align-items:center;margin:32px 0 16px}.section-title p{font-size:12px}.tag{font-size:10px;padding:6px 9px;border-radius:5px;background:#eef4ff;color:var(--navy)}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.filters input,.filters select{background:white;border:1px solid var(--line);border-radius:7px;padding:10px;color:var(--muted);font-size:11px;min-width:110px}.filters input:first-child{flex:1;min-width:160px}.filters button{font-size:11px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:white;border:1px solid var(--line);border-radius:12px;padding:22px;transition:box-shadow .2s}.card:hover{box-shadow:0 6px 20px #0033a00a}.card-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.id{font-size:10px;color:var(--muted);letter-spacing:.5px}.badge{font-size:9px;border:1px solid #cfdef5;background:#f1f6ff;color:var(--navy);padding:5px 7px;border-radius:5px;overflow-wrap:anywhere}.badge.warn{color:#79521a;background:#fff7e8;border-color:#f0d6a3}.card h3{font-size:18px;margin:17px 0 6px;letter-spacing:-.4px}.location{font-size:11px;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);margin:20px 0;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.metrics b{display:block;font-size:17px;margin-bottom:5px}.metrics small{font-size:10px}.line{font-size:11px;margin:11px 0;display:flex;gap:10px;line-height:1.5}.line label{color:var(--muted);min-width:85px}.blocker{background:#fff8ec;padding:10px 12px;border-radius:6px;color:#79521a;font-size:11px;line-height:1.5}.docs{display:flex;gap:5px;flex-wrap:wrap;margin:15px 0}.docs span{font-size:8px;border-bottom:1px solid #ccd8e9;padding-bottom:3px;color:var(--muted)}.card-bottom{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);padding-top:14px;margin-top:12px}.avatar{background:#e9f4ff;color:var(--navy);padding:7px;border-radius:50%;font-size:10px}.card-bottom button{font-size:11px;border:0;padding:5px}.empty{padding:60px;text-align:center;color:var(--muted);background:white;border:1px dashed var(--line);border-radius:12px}footer{font-size:10px;color:var(--muted);display:flex;justify-content:space-between;padding:30px 0}dialog{border:0;border-radius:16px;padding:28px;max-width:1000px;width:92vw;max-height:90vh;box-shadow:0 20px 100px #0033a033}dialog::backdrop{background:#142d4a80}.modal-head{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:20px}.tabs{display:flex;gap:5px;border-bottom:1px solid var(--line);padding-bottom:10px;flex-wrap:wrap}.tabs button{font-size:11px;border:0}.tabs button.active{background:#e9f4ff}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:20px 0}label.field{font-size:11px;color:var(--muted);display:block}.field input,.field select,.field textarea{display:block;width:100%;padding:10px;margin-top:7px;border:1px solid #cbd7e5;border-radius:6px;background:white;color:var(--ink)}.field textarea{min-height:75px}.full{grid-column:1/-1}.panel{background:#f3f7fd;padding:16px;border-radius:8px;margin:16px 0;line-height:1.7;font-size:12px}.actions{display:flex;gap:8px;justify-content:flex-end;margin-top:20px;flex-wrap:wrap}table{border-collapse:collapse;width:100%;font-size:11px;margin:18px 0}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:500;background:#f5f8fc}.table-wrap{overflow:auto}a{color:var(--navy)}#toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:var(--navy);color:white;padding:14px 22px;border-radius:8px;display:none;z-index:10;max-width:90vw}.checklist label{display:block;padding:12px;border-bottom:1px solid var(--line);font-size:12px}.checklist input{margin-right:10px}.pill{display:inline-block;font-size:10px;background:#e9f4ff;border-radius:5px;padding:5px;margin:4px} @media(min-width:1600px){main{max-width:1800px}.cards{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:1100px){aside{width:190px;padding:25px 12px}aside img{width:165px}main{margin-left:190px;padding:0 20px}.route{display:block}.steps{margin-top:15px}.cards{grid-template-columns:1fr}.notice{flex-wrap:wrap}.notice span{flex-basis:75%}}@media(max-width:700px){aside{position:static;width:auto;height:auto;padding:15px;border-right:0;border-bottom:1px solid var(--line)}aside img{width:160px}.space-label,aside h3,.side-bottom{display:none}nav{display:flex;overflow:auto;margin-top:12px}nav button{white-space:nowrap;width:auto;margin:0;font-size:11px;padding:10px}nav .ico,nav .count{display:none}main{margin:0;padding:0 16px}header{height:48px}header button{display:none}.heading{padding:24px 0;align-items:flex-start;gap:12px}h1{font-size:23px}.heading p{font-size:12px}.primary{padding:11px;font-size:11px;white-space:nowrap}.stats{grid-template-columns:repeat(2,1fr);gap:10px}.stat{padding:15px}.steps{flex-wrap:wrap;font-size:8px;gap:5px}.notice span{flex-basis:100%}.filters>*{flex:1;width:calc(50% - 8px)}.card{padding:18px}.form-grid{grid-template-columns:1fr}.full{grid-column:auto}footer{display:block;line-height:1.8}footer span{display:block}dialog{padding:18px}.section-title h2{font-size:18px}}\n</style></head><body><aside><img src=\"https://cdn.jsdelivr.net/gh/tehnoholod369-glitch/tehnoholod-katalog@main/novy-dizayn/assets/logo-369-horizontal-compact.png\" alt=\"ТехноХолод 369\"><div class=\"space-label\">РАБОЧЕЕ ПРОСТРАНСТВО</div><h3>ПУЛЬТ 369 <small>/ T-018</small></h3><nav id=\"nav\"></nav><div class=\"side-bottom\"><span class=\"dot\"></span> Модуль SSOT<br><small>Инженерные решения<br>ИП «ТехноХолод»</small></div></aside><main><header><span>ПУЛЬТ 369 <b> / </b> Инженерные системы <b> / </b> T-018</span><button id=\"guide\">Как работает модуль ↗</button></header><section class=\"heading\"><div><div class=\"eyebrow\">T-018 · ИНЖЕНЕРНЫЙ ПРОЦЕСС</div><h1>Мультисплит и Mini-VRF</h1><p>От исходных данных объекта до проверенного предложения.</p></div><button class=\"primary\" id=\"new\">＋ Новая заявка</button></section><div class=\"notice\"><strong>Тестовый контур интерфейса</strong><span> SSOT не подключён · изменения живут только до перезагрузки. Отправка поставщикам и выдача КП закрыты.</span><button id=\"connect\">Подключение →</button></div><div class=\"stats\" id=\"stats\"></div><section class=\"route\"><div><strong>Маршрут выпуска</strong><small>Переходы проходят через инженерный QA и решение владельца</small></div><div class=\"steps\"><span>01 DISCOVERED</span><i>→</i><span>02 DESIGNED</span><i>→</i><span>03 APPROVED</span><i>→</i><span>04 LIMITED_PRODUCTION</span></div></section><div class=\"section-title\"><div><h2 id=\"viewTitle\">Активные заявки</h2><p id=\"subtitle\">Объекты, которым нужен следующий шаг</p></div><span class=\"tag\">WIP <b id=\"wip\"></b> / 6</span></div><div class=\"filters\"><input id=\"search\" placeholder=\"Поиск по объекту или ID…\" aria-label=\"Поиск\"><select id=\"status\" aria-label=\"Статус\"></select><select id=\"owner\" aria-label=\"Владелец\"></select><select id=\"supplier\" aria-label=\"Поставщик\"></select><select id=\"system\" aria-label=\"Тип системы\"></select><select id=\"city\" aria-label=\"Город\"></select><input type=\"date\" id=\"date\" aria-label=\"Дата заявки\"><button id=\"reset\">Сбросить</button></div><div id=\"content\"></div><footer>ИП «ТехноХолод» <span>Единый источник данных — ПУЛЬТ 369 / SSOT · T-018</span></footer></main><dialog id=\"modal\"><div id=\"modalBody\"></div></dialog><div id=\"toast\" role=\"status\"></div><script>const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst statuses=['IN_PROGRESS','ENGINEER_REVIEW_REQUIRED','LEAD_SUBMITTED_TEST','LEAD_SUBMISSION_FAILED','PRICE_UNAVAILABLE'],routes=['DISCOVERED','DESIGNED','APPROVED','LIMITED_PRODUCTION'],docs=['ISSUES.md','TEST_MATRIX.md','QA_INDEPENDENT.md','RELEASE_CANDIDATE.md','FINAL_READBACK.md'];\nconst titles=['Активные заявки','Инженерная проверка','Проблемы и блокеры','Тестовые отправки','Финальный read-back'];let view=0,selected=null,tab=0;\nconst samples=[['018-001','Офис · независимые зоны','Алматы','Мультисплит',128,4,'14,0','ENGINEER_REVIEW_REQUIRED','DESIGNED','Инженер','DDC','Уточнить допустимую длину трассы','Проверить сочетание блоков и питание'],['018-002','Коттедж · два этажа','Астана','Mini-VRF',246,8,'28,0','PRICE_UNAVAILABLE','DISCOVERED','Менеджер','GM','Нет подтверждённого КП поставщика','Запросить цену с НДС и срок поставки'],['018-003','Клиника · кабинеты','Шымкент','Mini-VRF',190,6,'22,4','IN_PROGRESS','DISCOVERED','Инженер','Не выбран','Требуется план размещения блоков','Получить план и требования к шуму'],['018-004','Шоурум · торговый зал','Алматы','Мультисплит',96,3,'10,5','LEAD_SUBMITTED_TEST','DESIGNED','Менеджер','DDC','Тест без реальной отправки','Проверить структуру запроса КП'],['018-005','Офис · переговорные','Кызылорда','Мультисплит',84,3,'9,0','LEAD_SUBMISSION_FAILED','DISCOVERED','Менеджер','Не выбран','SSOT не подключён','Подключить исходную карточку ПУЛЬТ 369']];\nlet records=samples.map((a,i)=>({id:a[0],name:a[1],city:a[2],system:a[3],area:a[4],units:a[5],power:a[6],status:a[7],route:a[8],owner:a[9],supplier:a[10],blocker:a[11],next:a[12],date:'2026-11-10',rooms:'Уточняется',electric:'Не подтверждено',pipes:'Не подтверждено',temperature:'Не подтверждено',installation:'Нужно обследование',documents:'План объекта не получен',evidence:'Тестовый сценарий интерфейса. Не является инженерным заключением.',checks:{},options:[],history:[],qa:false,approved:false}));\nfunction toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}\nfunction options(el,label,values){$(el).innerHTML=`<option value=\"\">${label}</option>`+[...new Set(values)].map(v=>`<option>${esc(v)}</option>`).join('')}\nfunction filters(){options('#status','Все статусы',statuses);for(const [id,label,key] of [['owner','Все владельцы','owner'],['supplier','Все поставщики','supplier'],['system','Все системы','system'],['city','Все города','city']])options('#'+id,label,records.map(r=>r[key]))}\nfunction filtered(){return records.filter(r=>(!view||view===1&&r.status==='ENGINEER_REVIEW_REQUIRED'||view===2&&r.blocker||view===3&&['LEAD_SUBMITTED_TEST','LEAD_SUBMISSION_FAILED'].includes(r.status)||view===4)&&['status','owner','supplier','system','city','date'].every(k=>!$('#'+k).value||r[k]===$('#'+k).value)&&(!$('#search').value||(r.name+' '+r.id).toLowerCase().includes($('#search').value.toLowerCase())))}\nfunction render(){const counts=[records.length,records.filter(r=>r.status==='ENGINEER_REVIEW_REQUIRED').length,records.filter(r=>r.blocker).length,records.filter(r=>r.status.includes('LEAD_')).length];$('#nav').innerHTML=titles.map((n,i)=>`<button data-view=\"${i}\" class=\"${view===i?'active':''}\"><span class=\"ico\">${['▦','◎','⚑','↗','☷'][i]}</span>${n}<span class=\"count\">${counts[i]??records.length}</span></button>`).join('');$('#stats').innerHTML=[['В работе',records.length,'Тестовые заявки','▦'],['Ожидают инженера',counts[1],'Проверка совместимости','◎'],['Есть блокеры',counts[2],'Нужны подтверждения','⚑'],['Готовы к выдаче',0,'OWNER APPROVE обязателен','↗']].map(s=>`<div class=\"stat\"><span class=\"stat-icon\">${s[3]}</span><label>${s[0]}</label><b>${s[1].toString().padStart(2,'0')}</b><small>${s[2]}</small></div>`).join('');$('#viewTitle').textContent=titles[view];$('#subtitle').textContent=['Объекты, которым нужен следующий шаг','Совместимость, ограничения и инженерное заключение','Неполные данные и условия, которые мешают выпуску','Изолированная проверка без отправки поставщикам','Контроль результата перед финальной выдачей'][view];$('#wip').textContent=records.length;\nconst list=filtered();$('#content').innerHTML=list.length?`<div class=\"cards\">${list.map(r=>`<article class=\"card\"><div class=\"card-top\"><span class=\"id\">T-${esc(r.id)} · ТЕСТ</span><span class=\"badge ${r.status==='IN_PROGRESS'?'':'warn'}\">${esc(r.status)}</span></div><h3>${esc(r.name)}</h3><div class=\"location\">${esc(r.city)} <span> · </span> ${esc(r.system)} <span> · </span> ${esc(r.date)}</div><div class=\"metrics\"><div><b>${esc(r.area)} м²</b><small>Площадь объекта</small></div><div><b>${esc(r.units)} блока</b><small>Внутренние блоки</small></div><div><b>${esc(r.power)} кВт</b><small>Задание, не расчёт</small></div></div><div class=\"line\"><label>Маршрут / WIP</label><span>${esc(r.route)} · 1</span></div><div class=\"line\"><label>Следующий шаг</label><strong>${esc(r.next)}</strong></div><div class=\"blocker\">Блокер: ${esc(r.blocker||'Не указан')}</div><div class=\"line\"><label>Evidence</label><span>${esc(r.evidence)}</span></div>${view===4?`<div class=\"panel\">QA: ${r.qa?'тест пройден':'не пройден'} · OWNER APPROVE: нет<br>Выдача: заблокирована — SSOT не подключён</div>`:''}<div class=\"docs\">${docs.map(d=>`<span>${r.checks[d]?'✓':'○'} ${d}</span>`).join('')}</div><div class=\"card-bottom\"><span><span class=\"avatar\">${r.owner==='Инженер'?'ИН':'МН'}</span> <small>${esc(r.owner)} · ${esc(r.supplier)}</small></span><button data-open=\"${esc(r.id)}\">Открыть заявку ↗</button></div></article>`).join('')}</div>`:'<div class=\"empty\">Заявок по этим условиям нет. Измените фильтры.</div>'}\n$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b){view=+b.dataset.view;render()}};$('#content').onclick=e=>{const b=e.target.closest('[data-open]');if(b){selected=records.find(r=>r.id===b.dataset.open);tab=0;detail()}};\nfunction modal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modalBody').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}\nfunction field(key,label,type='text'){return `<label class=\"field\">${label}<input name=\"${key}\" type=\"${type}\" value=\"${esc(selected[key])}\" ${['area','units'].includes(key)?'min=\"1\" required':''}></label>`}\nfunction pick(key,label,opts){return `<label class=\"field\">${label}<select name=\"${key}\">${opts.map(o=>`<option ${selected[key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}\nfunction detail(){const r=selected;modal(`<div class=\"modal-head\"><div><div class=\"eyebrow\">ТЕСТ · T-${esc(r.id)}</div><h2>${esc(r.name)}</h2></div><button data-close aria-label=\"Закрыть\">✕</button></div><div class=\"tabs\">${['Исходные данные','Подбор и поставщики','Инженерный QA','Лиды и запрос КП','Read-back'].map((t,i)=>`<button data-tab=\"${i}\" class=\"${tab===i?'active':''}\">${t}</button>`).join('')}</div><div id=\"detailContent\"></div>`);$('.tabs').onclick=e=>{if(e.target.dataset.tab){tab=+e.target.dataset.tab;detail()}};\nif(tab===0){$('#detailContent').innerHTML=`<form id=\"edit\"><div class=\"form-grid\">${field('name','Название объекта')}${field('city','Город')}${pick('system','Тип системы',['Мультисплит','Mini-VRF'])}${field('area','Площадь, м²','number')}${field('units','Внутренних блоков','number')}${field('power','Требуемая мощность, кВт')}${field('rooms','Типы помещений')}${field('electric','Электропитание: фазы, кВт, резерв')}${field('pipes','Трассы: длина, перепад, дренаж')}${field('temperature','Температурный режим, °C')}${field('installation','Монтаж: доступ, фасад, шум')}${field('documents','Документы и планировки')}${field('owner','Владелец')}${field('supplier','Поставщик')}${pick('status','Статус',statuses)}${field('blocker','Блокеры')}${field('next','Следующий шаг')}${field('evidence','Evidence / ссылка или описание')}<div class=\"full panel\">Все числа в примерах — тестовое задание. Автоматический расчёт по площади не заменяет теплотехнический расчёт. Предварительный подбор подтверждает инженер.</div></div><div class=\"actions\"><button type=\"submit\">Сохранить тестовый черновик</button></div></form>`;$('#edit').onsubmit=e=>{e.preventDefault();Object.assign(r,Object.fromEntries(new FormData(e.target)));r.qa=false;r.approved=false;r.checks={};r.route='DISCOVERED';filters();render();toast('Черновик изменён в памяти. QA и согласование сброшены.')}}\nif(tab===1){$('#detailContent').innerHTML=`<div class=\"panel\">Сравнивайте только документально совместимые сочетания наружного и внутренних блоков. Цена — за весь указанный комплект, с НДС. Непроверенные и просроченные данные блокируют выпуск.</div><div class=\"table-wrap\"><table><thead><tr><th>Модель / поставщик</th><th>Мощность</th><th>Цена с НДС, ₸</th><th>Наличие / срок</th><th>QA / источник</th></tr></thead><tbody>${r.options.length?r.options.map(o=>`<tr><td>${esc(o.model)}<br>${esc(o.supplier)}</td><td>${esc(o.capacity)} кВт</td><td>${esc(o.price||'PRICE_UNAVAILABLE')}</td><td>${esc(o.stock)}<br>${esc(o.delivery)}</td><td>Не проверено<br>${safeLink(o.source)}<br>VERIFIED_AT: ${esc(o.verified||'нет')}<br>VALIDITY: ${esc(o.validity||'нет')}</td></tr>`).join(''):'<tr><td colspan=\"5\">Подтверждённых моделей нет. Добавьте данные из КП поставщика.</td></tr>'}</tbody></table></div><form id=\"option\"><div class=\"form-grid\">${['model|Модель / сочетание блоков','supplier|Поставщик','capacity|Мощность, кВт','price|VALUE: цена комплекта с НДС, ₸','stock|VALUE: наличие','delivery|VALUE: срок поставки','source|SOURCE: URL документа','verified|VERIFIED_AT: дата проверки','validity|FRESHNESS / VALIDITY: действительно до'].map(x=>{const[k,l]=x.split('|');return `<label class=\"field\">${l}<input name=\"${k}\" ${['model','supplier','source'].includes(k)?'required':''} ${k==='source'?'type=\"url\"':k==='verified'||k==='validity'?'type=\"date\"':k==='price'||k==='capacity'?'type=\"number\" min=\"0\" step=\"0.01\"':''}></label>`}).join('')}</div><button>Добавить вариант в сравнение</button></form>`;$('#option').onsubmit=e=>{e.preventDefault();r.options.push(Object.fromEntries(new FormData(e.target)));r.qa=false;r.approved=false;r.checks={};detail();toast('Вариант добавлен как непроверенный. Источник требует инженерного QA.')}}\nif(tab===2){$('#detailContent').innerHTML=`<div class=\"panel\">Маршрут: <b>${r.route}</b> · WIP: 1 · Владелец: ${esc(r.owner)}<br>Инженерная проверка: питание, длины и перепады трасс, диапазоны температуры, допустимые сочетания блоков, монтаж, документы и комплектность цены.</div><div class=\"checklist\">${docs.map(d=>`<label><input type=\"checkbox\" data-doc=\"${d}\" ${r.checks[d]?'checked':''}>${d} — тестовая отметка, файл SSOT не изменяется</label>`).join('')}<label><input id=\"qa\" type=\"checkbox\" ${r.qa?'checked':''}>Инженерный QA выполнен (тест)</label></div><div class=\"actions\"><button id=\"design\">Перевести в DESIGNED</button><button disabled>OWNER APPROVE · SSOT не подключён</button></div><p>APPROVED → LIMITED_PRODUCTION доступны только после авторизованного OWNER APPROVE в SSOT, независимого QA, свежих цен и закрытия блокеров.</p>`;document.querySelectorAll('[data-doc]').forEach(i=>i.onchange=()=>{r.checks[i.dataset.doc]=i.checked;render()});$('#qa').onchange=e=>{r.qa=e.target.checked;render()};$('#design').onclick=()=>{if(!r.qa||!r.evidence.trim()||!docs.slice(0,3).every(d=>r.checks[d]))return toast('Нужны QA, evidence и первые три отметки документов.');if(r.route!=='DISCOVERED')return toast('Текущий этап уже DESIGNED.');r.route='DESIGNED';r.status='ENGINEER_REVIEW_REQUIRED';render();detail();toast('Тестовый этап DESIGNED. Реальное согласование не выполнено.')}}\nif(tab===3){$('#detailContent').innerHTML=`<div class=\"panel\"><b>Запрос КП поставщику</b><br>Объект: ${esc(r.name)} · ${esc(r.city)}<br>${esc(r.system)} · ${esc(r.area)} м² · ${esc(r.units)} внутренних блоков · ${esc(r.power)} кВт<br>Питание: ${esc(r.electric)}. Трассы: ${esc(r.pipes)}.<br>Температура: ${esc(r.temperature)}. Монтаж: ${esc(r.installation)}.<br>Документы: ${esc(r.documents)}.<br>Просим указать сочетание блоков, цену комплекта с НДС, наличие, срок поставки, срок действия и ссылки на подтверждающие документы.</div><p>Тест проверяет структуру запроса и обязательные поля. Письма и лиды не отправляются.</p><div class=\"actions\"><button id=\"testFail\">Проверить сценарий ошибки</button><button id=\"testLead\">Выполнить тест отправки</button><button disabled>Отправить поставщику · нет SSOT</button></div><div class=\"panel\">${r.history.length?r.history.map(h=>esc(h)).join('<br>'):'Новых тестовых событий нет.'}</div>`;$('#testLead').onclick=()=>{const ok=['name','city','area','units','power','owner','supplier'].every(k=>String(r[k]).trim()&&r[k]!=='Не выбран');r.status=ok?'LEAD_SUBMITTED_TEST':'LEAD_SUBMISSION_FAILED';r.history.push(new Date().toISOString()+' · '+r.status+' · Только локальный тест, внешний запрос отсутствует');render();detail()};$('#testFail').onclick=()=>{r.status='LEAD_SUBMISSION_FAILED';r.history.push(new Date().toISOString()+' · LEAD_SUBMISSION_FAILED · Тест: источник SSOT недоступен');render();detail()}}\nif(tab===4){$('#detailContent').innerHTML=`<div class=\"panel\"><b>FINAL_READBACK.md · T-${esc(r.id)}</b><br>Объект: ${esc(r.name)} · ${esc(r.city)}<br>Владелец: ${esc(r.owner)} · WIP: 1<br>Статус: ${esc(r.status)} · Маршрут: ${esc(r.route)}<br>Блокеры: ${esc(r.blocker||'Не указаны')}<br>Следующий шаг: ${esc(r.next)}<br>Evidence: ${esc(r.evidence)}<br>Инженерный QA: ${r.qa?'отмечен в тесте':'не пройден'}<br>OWNER APPROVE: отсутствует<br>Цена с НДС / наличие / поставка: не подтверждены<br>Связь с SSOT: отсутствует<br>Итог: <b>ВЫДАЧА КП ЗАБЛОКИРОВАНА</b></div><div class=\"actions\"><button id=\"download\">Скачать тестовый read-back</button><button disabled>Выдать финальное КП</button></div>`;$('#download').onclick=()=>download(`T-${r.id}-TEST-READBACK.json`,{kind:'TEST_ONLY_NOT_SSOT',...r,owner_approve:false,release_allowed:false})}}\nfunction safeLink(s){try{let u=new URL(s);return ['http:','https:'].includes(u.protocol)?`<a href=\"${esc(u.href)}\" target=\"_blank\" rel=\"noopener noreferrer\">Источник ↗</a>`:'Недопустимая ссылка'}catch{return 'Источник не указан'}}\nfunction download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}\n$('#new').onclick=()=>{if(records.length>=6)return toast('Лимит WIP 6 достигнут. Завершите существующую заявку.');selected={id:'018-'+String(records.length+1).padStart(3,'0'),name:'Новый объект',city:'',system:'Мультисплит',area:1,units:1,power:'',rooms:'',electric:'',pipes:'',temperature:'',installation:'',documents:'',owner:'Не назначен',supplier:'Не выбран',status:'IN_PROGRESS',route:'DISCOVERED',date:new Date().toISOString().slice(0,10),blocker:'Исходные данные не собраны',next:'Заполнить исходные данные',evidence:'',checks:{},options:[],history:[],qa:false,approved:false};records.push(selected);filters();render();tab=0;detail()};\n$('#connect').onclick=()=>modal(`<div class=\"modal-head\"><h2>Подключение к ПУЛЬТ 369 / SSOT</h2><button data-close>✕</button></div><p>Модуль не создаёт вторую базу заявок. Для рабочего режима нужны адрес существующего SSOT, схема карточки, авторизация владельца и согласованный API.</p><div class=\"panel\">Ключ: существующий ID заявки SSOT.<br>Изменяемые значения: VALUE, SOURCE, VERIFIED_AT, FRESHNESS / VALIDITY.<br>OWNER APPROVE: серверное решение владельца с датой и evidence.<br>Отправки: подтверждение результата источником и защита от повторов.<br>Согласование аннулируется при изменении карточки или цены.<br>Текущий режим: тестовые записи в памяти страницы, без синхронизации.</div><button data-close>Понятно</button>`);\n$('#guide').onclick=()=>modal(`<div class=\"modal-head\"><h2>Один объект — один маршрут</h2><button data-close>✕</button></div><div class=\"panel\">1. Соберите исходные данные и ограничения.<br>2. Сравните сочетания блоков и предложения поставщиков.<br>3. Сформируйте запрос КП и проверьте тестовую отправку.<br>4. Пройдите инженерный QA и зафиксируйте evidence.<br>5. Получите OWNER APPROVE в действующем SSOT.<br>6. Проверьте read-back и выдайте КП в LIMITED_PRODUCTION.</div><p>DISCOVERED → DESIGNED → APPROVED → LIMITED_PRODUCTION. Инженерная совместимость не определяется только площадью или суммой мощностей. Подтверждение — документация производителя и заключение инженера.</p><button data-close>Начать работу</button>`);\nfor(const id of ['search','status','owner','supplier','system','city','date'])$('#'+id).addEventListener(id==='search'?'input':'change',render);$('#reset').onclick=()=>{document.querySelectorAll('.filters input,.filters select').forEach(i=>i.value='');render()};filters();render();\n</script></body></html>\n";document.body.appendChild(f)})();